{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": []
  },
  "frozen_questions": [
    {
      "gap": "簡文帝為何見到桓宣武就掉淚？是悲痛、恐懼還是另有所感？",
      "question_id": "Q1",
      "story_span": "簡文便泣下數\n十行"
    },
    {
      "gap": "「不甚得語」的具體含義與原因（是不善言辭，還是兩人關係緊張）缺失，影響對桓宣武為何預撰演說的理解。",
      "question_id": "Q2",
      "story_span": "桓宣武對簡文帝不甚得語"
    },
    {
      "gap": "桓宣武所撰數百語的具體內容缺失——他如何辯護廢海西、立簡文帝，這決定了後文沉默的諷刺力量。",
      "question_id": "Q3",
      "story_span": "乃\n豫撰數百語陳廢立之意"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": []
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "桓宣武對簡文帝不甚得語廢海西後宜自申叙乃\n豫撰數百語陳廢立之意既見簡文簡文便泣下數\n十行宣武矜愧不得一言"
  },
  "story_id": "33-youhui-012"
}
